import 'package:shia_hijri_calendar/shia_hijri_calendar.dart';
import 'package:quran/quran.dart' as quran;
// models/shia_data.dart

class QuranVerse {
  final int number;
  final String text;
  final String translation;
  final String tafsir;

  QuranVerse({
    required this.number,
    required this.text,
    required this.translation,
    required this.tafsir,
  });
}

class Surah {
  final String name;
  final String englishName;
  final String type; // مكة / المدينة
  final List<QuranVerse> verses;

  Surah({
    required this.name,
    required this.englishName,
    required this.type,
    required this.verses,
  });
}

class Dua {
  final String title;
  final String text;
  final String benefits;

  Dua({required this.title, required this.text, required this.benefits});
}

class Ziyarat {
  final String title;
  final String text;
  final String benefits;

  Ziyarat({required this.title, required this.text, required this.benefits});
}

class HijriEvent {
  final int day;
  final int month; // 1 to 12
  final String title;
  final String description;
  final String recommendedActs;
  final bool isMartyrdom;

  HijriEvent({
    required this.day,
    required this.month,
    required this.title,
    required this.description,
    required this.recommendedActs,
    this.isMartyrdom = false,
  });
}

class ShiaData {
  static final List<Surah> surahs = List.generate(114, (index) {
    final surahNumber = index + 1;
    final count = quran.getVerseCount(surahNumber);
    return Surah(
      name: quran.getSurahNameArabic(surahNumber),
      englishName: quran.getSurahName(surahNumber),
      type: quran.getPlaceOfRevelation(surahNumber) == "Makkah"
          ? "مكية"
          : "مدنية",
      verses: List.generate(count, (vIndex) {
        final verseNum = vIndex + 1;
        return QuranVerse(
          number: verseNum,
          text: quran.getVerse(surahNumber, verseNum, verseEndSymbol: true),
          translation: "",
          tafsir: "",
        );
      }),
    );
  });

  static final List<Dua> duas = [
    Dua(
      title: 'يا من تحل به عُقد المكاره',
      benefits: 'دعاء الامام السجاد عليه السلام في المُهمّات اذا عرضت له مهمّة أو نزلت ملّهمة و عند الكرب',
      text: '''يا من تُحلُّ به عُقدُ المكاره، ويا من يُفثأُ به حدُّ الشّدائد، ويا من يُلتمسُ منهُ المخرجُ إلى روح الفرج، ذلّت لقُدرتك الصّعابُ وتسبّبت بلُطفك الاسبابُ، وجرى بقُدرتك القضاءُ ومضت على إرادتك الاشياءُ، فهي بمشيّتك دُون قولك مُؤتمرةٌ، وبإرادتك دُون نهيك مُنزجرةٌ. أنت المدعُوُّ للمُهمّات، وأنت المفزعُ في المُلمّات، لايندفعُ منها إلاّ ما دفعت، ولا ينكشفُ منها إلاّ ما كشفت. وقد نزل بي يا ربّ ما قد تكأدنيّ ثقلُهُ، وألمّ بي ما قد بهظني حملُهُ، وبقُدرتك أوردتهُ عليّ وبسُلطانك وجّهتهُ إليّ. فلا مُصدر لما أوردت، ولا صارف لما وجّهت، ولا فاتح لما أغلقت، ولا مُغلق لما فتحت، ولا مُيسّر لما عسّرت، ولا ناصر لمن خذلت فصلّ على مُحمّد وآله، وافتح لي يا ربّ باب الفرج بطولك، واكسر عنّي سُلطان الهمّ بحولك، وأنلني حُسن ألنّظر فيما شكوتُ، وأذقني حلاوة الضُّنع فيما سالتُ. وهب لي من لدُنك رحمةً وفرجاً هنيئاً واجعل لي من عندك مخرجاً وحيّاً. ولا تشغلني بالاهتمام عن تعاهُد فُرُوضك واستعمال سُنّتك. فقد ضقتُ لما نزل بي يا ربّ ذرعاً، وامتلاتُ بحمل ما حدث عليّ همّاً، وأنت القادرُ على كشف مامُنيتُ به، ودفع ماوقعتُ فيه، فافعل بي ذلك وإن لم أستوجبهُ منك، يا ذا العرش العظيم  .''',
    ),
    Dua(
      title: 'دعاء العهد',
      benefits: 'روي عن الصادق (عليه السلام) أنه قال : من دعا إلى الله تعالى أربعين صباحاً بهذا العهد كان من أنصار قائمنا، فإن مات قبله أخرجه الله تعالى من قبره ....',
      text: '''بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ

اَللَّهُمَّ رَبَّ النُّورِ الْعَظِيمِ وَرَبَّ الْكُرْسِيِّ الرَّفِيعِ وَرَبَّ الْبَحْرِ الْمَسْجُورِ وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالزَّبُورِ وَرَبَّ الظِّلِّ وَالْحَرُورِ وَمُنْزِلَ الْقُرْآنِ الْعَظِيمِ وَرَبَّ الْمَلَائِكَةِ الْمُقَرَّبِينَ وَالْأَنْبِيَاءِ وَالْمُرْسَلِينَ اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِوَجْهِكَ الْكَرِيمِ وَبِنُورِ وَجْهِكَ الْمُنِيرِ وَمُلْكِكَ الْقَدِيمِ يَا حَيُّ يَا قَيُّومُ أَسْأَلُكَ بِاسْمِكَ الَّذِي أَشْرَقَتْ بِهِ السَّمَاوَاتُ وَالْأَرَضُونَ وَبِاسْمِكَ الَّذِي يَصْلُحُ بِهِ الْأَوَّلُونَ وَالْآخِرُونَ يَا حَيًّا قَبْلَ كُلِّ حَيٍّ وَيَا حَيًّا بَعْدَ كُلِّ حَيٍّ وَيَا حَيًّا حِينَ لَا حَيَّ يَا مُحْيِيَ الْمَوْتَى وَمُمِيتَ الْأَحْيَاءِ يَا حَيُّ لَا إِلَهَ إِلَّا أَنْتَ اَللَّهُمَّ بَلِّغْ مَوْلَانَا الْإِمَامَ الْهَادِيَ الْمَهْدِيَّ الْقَائِمَ بِأَمْرِكَ صَلَوَاتُ اللَّهِ عَلَيْهِ وَعَلَى آبَائِهِ الطَّاهِرِينَ عَنْ جَمِيعِ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ فِي مَشَارِقِ الْأَرْضِ وَمَغَارِبِهَا سَهْلِهَا وَجَبَلِهَا وَبَرِّهَا وَبَحْرِهَا وَعَنِّي وَعَنْ وَالِدَيَّ مِنَ الصَّلَوَاتِ زِنَةَ عَرْشِ اللَّهِ وَمِدَادَ كَلِمَاتِهِ وَمَا أَحْصَاهُ عِلْمُهُ وَأَحَاطَ بِهِ كِتَابُهُ اَللَّهُمَّ إِنِّي أُجَدِّدُ لَهُ فِي صَبِيحَةِ يَوْمِي هَذَا وَمَا عِشْتُ مِنْ أَيَّامِي عَهْدًا وَعَقْدًا وَبَيْعَةً لَهُ فِي عُنُقِي لَا أَحُولُ عَنْهَا وَلَا أَزُولُ أَبَدًا اَللَّهُمَّ اجْعَلْنِي مِنْ أَنْصَارِهِ وَأَعْوَانِهِ وَالذَّابِّينَ عَنْهُ وَالْمُسَارِعِينَ إِلَيْهِ فِي قَضَاءِ حَوَائِجِهِ وَالْمُمْتَثِلِينَ لِأَوَامِرِهِ وَالْمُحَامِينَ عَنْهُ وَالسَّابِقِينَ إِلَى إِرَادَتِهِ وَالْمُسْتَشْهَدِينَ بَيْنَ يَدَيْهِ اَللَّهُمَّ إِنْ حَالَ بَيْنِي وَبَيْنَهُ الْمَوْتُ الَّذِي جَعَلْتَهُ عَلَى عِبَادِكَ حَتْمًا مَقْضِيًّا فَأَخْرِجْنِي مِنْ قَبْرِي مُؤْتَزِرًا كَفَنِي شَاهِرًا سَيْفِي مُجَرِّدًا قَنَاتِي مُلَبِّيًا دَعْوَةَ الدَّاعِي فِي الْحَاضِرِ وَالْبَادِي اَللَّهُمَّ أَرِنِي الطَّلْعَةَ الرَّشِيدَةَ وَالْغُرَّةَ الْحَمِيدَةَ وَاكْحُلْ نَاظِرِي بِنَظْرَةٍ مِنِّي إِلَيْهِ وَعَجِّلْ فَرَجَهُ وَسَهِّلْ مَخْرَجَهُ وَأَوْسِعْ مَنْهَجَهُ وَاسْلُكْ بِي مَحَجَّتَهُ وَأَنْفِذْ أَمْرَهُ وَاشْدُدْ أَزْرَهُ وَاعْمُرِ اللَّهُمَّ بِهِ بِلَادَكَ وَأَحْيِ بِهِ عِبَادَكَ فَإِنَّكَ قُلْتَ وَقَوْلُكَ الْحَقُّ ظَهَرَ الْفَسَادُ فِي الْبَرِّ وَالْبَحْرِ بِمَا كَسَبَتْ أَيْدِي النَّاسِ فَأَظْهِرِ اللَّهُمَّ لَنَا وَلِيَّكَ وَابْنَ بِنْتِ نَبِيِّكَ الْمُسَمَّى بِاسْمِ رَسُولِكَ حَتَّى لَا يَظْفَرَ بِشَيْءٍ مِنَ الْبَاطِلِ إِلَّا مَزَّقَهُ وَيُحِقَّ الْحَقَّ وَيُحَقِّقَهُ وَاجْعَلْهُ اللَّهُمَّ مَفْزَعًا لِمَظْلُومِ عِبَادِكَ وَنَاصِرًا لِمَنْ لَا يَجِدُ لَهُ نَاصِرًا غَيْرَكَ وَمُجَدِّدًا لِمَا عُطِّلَ مِنْ أَحْكَامِ كِتَابِكَ وَمُشَيِّدًا لِمَا وَرَدَ مِنْ أَعْلَامِ دِينِكَ وَسُنَنِ نَبِيِّكَ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ وَاجْعَلْهُ اللَّهُمَّ مِمَّنْ حَصَّنْتَهُ مِنْ بَأْسِ الْمُعْتَدِينَ اَللَّهُمَّ وَسُرَّ نَبِيَّكَ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ بِرُؤْيَتِهِ وَمَنْ تَبِعَهُ عَلَى دَعْوَتِهِ وَارْحَمِ اسْتِكَانَتَنَا بَعْدَهُ اَللَّهُمَّ اكْشِفْ هَذِهِ الْغُمَّةَ عَنْ هَذِهِ الْأُمَّةِ بِحُضُورِهِ وَعَجِّلْ لَنَا ظُهُورَهُ إِنَّهُمْ يَرَوْنَهُ بَعِيدًا وَنَرَاهُ قَرِيبًا بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ 

ثم تضرب على فخذك الأيمن بيدك ثلاث مرات وتقول كل مرة 

الْعَجَلَ الْعَجَلَ يَا مَوْلَايَ يَا صَاحِبَ الزَّمَانِ''',
    ),
    Dua(
      title: 'الدعاء الجامع',
      benefits: 'عن أبي حمزة قال: أخذت هذا الدعاء من الباقر عليه السلام وكان يسميه الدعاء الجامع',
      text: '''بِسْمِ الله الرَّحْمنِ الرَّحيمِ 

 أشْهَدُ أنْ لا إلهَ إِلاّ الله وَحَدَهُ لا شَريكَ لَهُ وَأشْهَدُ أنَّ مُحَمَّداً عَبْدُهُ وَرَسولُهُ، آمَنْتُ بِالله وَبِجَميعِ رُسُلِهِ وَبِجَميعِ ما أُنْزِلَ بِهِ عَلى جَميعِ الرُّسُلِ، وَأنَّ وَعْدَ الله حقٌ وَلِقاءهُ حَقٌ وَصَدَقَ الله وَبَلَّغَ المُرْسَلونَ وَالحَمْدُ لله ربِّ العالَمينَ وَسُبْحانَ الله كُلَّما سَبَّحَ الله شَيٌ وَكَما يُحِبُّ الله أنْ يُسَبِّحُ، وَالحَمْدُ لله كُلَّما حَمِدَ الله شَيٌ وَكَما يُحِبُّ الله أنْ يُحْمَدَ وَلا إلهَ إِلاّ الله كُلَّما هَلّلَ الله شَيٌ وَكَما يُحِبُّ الله أنْ يُهَلّلْ، والله أكْبَرُ كُلَّما كَبّرَ الله شَيٌ وَكَما يُحِبُّ الله أنْ يُكَبَّرَ.
اللّهُمَّ إِنِّي أَسْأَلُكَ مَفاتيحَ الخَيْرِ وَخَواتيمَهُ وَسَوابِغَهُ وفَوائِدَهُ وَبَرَكاتِهُ وَمابَلَغَ عِلْمَهُ عِلْمي وَماقَصُرَ عَنْ إحْصائِهِ حِفْظِي، اللّهُمَّ انْهَجْ لي أسْبابَ مَعْرِفَتِهِ وافْتَحْ لي أبْوابَهُ وَغَشِّني بَرَكاتِ رَحْمَتِكَ وَمُنَّ عَلَيَّ بِعِصْمَةٍ عَنْ الازالَةِ عَنْ دينِكَ وَطَهُرْ قَلْبي مِنَ الشَّكِ وَلا تَشْغِلْ قَلْبي بِدُنيايَ وَعاجِلِ مَعاشي عَنْ آجِلِ ثَوابِ آخِرَتي، وَاشْغِلْ قَلْبي بِحِفْظِ ما لا تَقْبَلْ مِنّي جَهْلَهُ وَذَلِّلْ لِكُلِّ خَيْرٍ لِساني وَطَهِّرْ قَلْبي مِنَ الرِّياءِ وَلا تُجْرِهِ في مَفاصِلي وَاجْعَلْ عَمَلي خالِصا لَكَ، اللّهُمَّ إِنِّي أعوذُ بِكَ مِنَ الشَرِّ وَأنْواعِ الفَواحِشِ كُلِّها ظاهِرِها وَباطِنِها وَغَفَلاتِها وَجَميعِ ما يُريدَني بِهِ الشَّيطانُ الرجيمُ وَما يُريدُني بِهِ السُّلطانُ العتيد مِمّا أحَطْتَ بِعِلْمِهِ وَأنْتَ القادِرُ عَلى صَرْفِهِ عَنّي، اللّهُمَّ إِنِّي أعوذُ بِكَ مِنْ طَوارِقِ الجِنِّ وَالانْسِ وَزَوابِعِهِمْ وَبَوائِقِهِم وَمَكايدِهِمْ وَمَشاهِدِ الفَسَقَةِ مِنَ الجِنِّ وَالانْسِ، وَأنْ أسْتَزِلَّ عَنْ ديني فَتَفْسُدُ عَلَيَّ آخِرَتي، وَأنْ يَكونَ ذلكَ مِنْهُمْ ضَرراً عَلَيَّ في مَعاشي أو يَعْرُضَ بَلاءٌ يُصيبُني مِنْهُمْ وَلا قوَّةَ لي بِهِ وَلا صَبْرَ لي عَلى احْتِمالِهِ، فَلا تَبْتَليني يا ألهي بِمُقاساتِهِ فَيَمْنَعُني ذلكَ عَنْ ذِكْرِكَ وَيَشْغَلُني عَنْ عِبادَتِكَ؛ أنْتَ العاصِمُ المانِعُ الدافِعُ الواقي مِنْ ذلكَ كُلِّهِ. أَسْأَلُكَ اللّهُمَّ الرَّفاهيَةَ في مَعيشَتي ما أبْقَيْتَني مَعيشَةً أقْوى بها عَلى طاعَتِكَ وَأبْلُغُ بِها رِضْوانَكَ وَأصيرُ بِها إِلى دارِ الحَيوانِ غَداً، وَلا تَرْزُقْني رِزْقاً يُطْغيني وَلا تَبْتَلِيَني بِفَقْرٍ أشْقى بِهِ مُضَيَّقا عَلَيَّ، أعْطِني حَظّا وَافراً في آخِرَتي وَمَعاشاً واسِعاً هَنيئاً مَريئاً في دُنْيايَ وَلا تَجْعَلْ الدُّنْيا عَلَيَّ سِجْناً وَلا تَجْعَلْ فِراقَها عَلَيَّ حُزْناً، أجِرْني مِنْ فِتْنَتِها وَاجْعَلْ عَمَلي فيها مَقْبولاً وَسَعْيي فيها مَشْكوراً، اللّهُمَّ وَمَنْ أرادَني بِسوءٍ فَأَرِدْهُ بِمِثْلِهِ وَمَنْ كادَني فيها فَكِدْهُ وَاصْرِفْ عَنّي هَمَّ مَنْ أَدْخَلَ عَلَيَّ هَمَّهُ وَامْكُرْ بِمَنْ مَكَرَ بي فَإنَّكَ خَيْرُ الماكِرينَ وَافْقاء عَنّي عُيونَ الكَفَرَةِ الظَّلَمَةِ الطُّغاةِ الحَسَدَةِ، اللّهُمَّ وَأنْزِلْ عَلَيَّ مِنْكَ السَّكينَةَ وألْبِسْني دِرْعَكَ ألحَصينَةَ وَاحْفِظْني بِسِرِّكَ الواقي وَجَلِّلْني عافيَتَكَ النَّافِعَةَ وَصَدِّقْ قَوْلي وَفِعالي وَبارِكْ لي في وَلَدي وَأَهْلي وَمالي، اللّهُمَّ ما قَدَّمْتُ وَما أَخَّرْتُ وَما أغْفَلْتُ وَما تَعَمَّدْتُ وَما تَوانَيْتُ وَما أعلنت وَما اسْرَرْتُ فَإغْفِرْ لي يا أرْحَمَ الرّاحِمينَ.''',
    ),
    Dua(
      title: 'دعاء جبرائيل عليه السلام',
      benefits: 'ومما قاله جبرائيل عليه السلام في فضل هذا الدعاء : يا محمد لو صارت أشجار الدنيا أقلاما والبحار مدادا والخلائق كتابا لم يقدروا على ثواب قارئ هذا الدعاء.',
      text: '''بسم الله الرحمن الرحيم

