  // =========================================================================
  // دوال البحث والمساعدات
  // =========================================================================

  static Surah? getSurahByName(String name) {
    for (var s in surahs) {
      if (s.name == name) return s;
    }
    return null;
  }

  static Dua? getDuaByTitle(String title) {
    for (var d in duas) {
      if (d.title == title) return d;
    }
    for (var d in dailyDuas) {
      if (d.title == title) return d;
    }
    for (var d in prayerDuas) {
      if (d.title == title) return d;
    }
    return null;
  }

  static Ziyarat? getZiyaratByTitle(String title) {
    for (var z in ziyarats) {
      if (z.title == title) return z;
    }
    for (var z in dailyZiyarats) {
      if (z.title == title) return z;
    }
    return null;
  }
}

class Dhikr {
  final String title;
  final String text;
  final String benefits;

  Dhikr({required this.title, required this.text, required this.benefits});
}
